example.code:
// Logging in pipelines without breaking the flow
var result = GetData()
    .Tap(d => logger.LogInformation("Processing {Count} items", d.Count))
    .ProcessData()
    .Tap(r => logger.LogInformation("Result: {Result}", r));

// Fluent object initialization
var client = new HttpClient()
    .Tap(c => c.Timeout = TimeSpan.FromSeconds(30))
    .Tap(c => c.DefaultRequestHeaders.Add("Authorization", token));

// Debugging without intermediate variables
var transformed = GetComplexData()
    .Select(x => x.Value)
    .Tap(v => Console.WriteLine($"Debug: {v}"))  // Inspect here
    .Where(v => v > 0);

// Linear pipeline (easy to read and debug)
var result = GetPerson()
    .Map(p => p.Address)
    .Map(a => a.City)
    .Map(c => c.ToUpper());

// vs. Nested calls (harder to read)
var result = GetPerson().Address.City.ToUpper();

// Pipeline with mixed operations
var city = GetPerson()
    .Tap(p => logger.LogDebug("Got person: {Name}", p.Name))
    .Map(p => p.Address)
    .Tap(a => logger.LogDebug("Got address: {Street}", a.Street))
    .Map(a => a.City);

// Safe logging of potentially null values
string? value = GetNullableString()
    .TapIfNotNull(v => logger.LogInformation("Got value: {Value}", v));

// Only execute initialization if object exists
var config = FindConfig()
    .TapIfNotNull(c => c.Initialize())
    .TapIfNotNull(c => logger.LogInformation("Config initialized"));

// Explicit null-safe pipeline
var city = GetPerson()
    .MapIfNotNull(p => p.Address)
    .MapIfNotNull(a => a.City)
    .MapIfNotNull(c => c.ToUpper());

// vs. Null-conditional chain (less explicit about the Map operation)
var city = GetPerson()?.Address?.City?.ToUpper();

var result = await GetDataAsync()
    .ThenTap(d => logger.LogInformation("Received {Count} items", d.Count))
    .ThenMap(d => ProcessData(d));

var result = await GetDataAsync()
    .ThenTapAsync(async (d, ct) => await LogToRemoteAsync(d, ct))
    .ThenMap(d => ProcessData(d));

var cityUpper = await GetPersonAsync()
    .ThenMap(p => p.Address)
    .ThenMap(a => a.City)
    .ThenMap(c => c.ToUpper());

var processed = await GetPersonAsync()
    .ThenMapAsync(async (p, ct) => await ProcessPersonAsync(p, ct))
    .ThenMapAsync(async (r, ct) => await SaveResultAsync(r, ct));

// Lazy evaluation - only processes what's needed
var result = Enumerable.Range(1, 1_000_000)
    .Where(x => x % 2 == 0)
    .Do(x => logger.LogDebug("Processing {Number}", x))  // Only logs what's consumed
    .Take(10)
    .ToList();  // Only 10 items are processed and logged

// Multiple Do calls for debugging pipeline stages
var cities = GetPeople()
    .Do(p => logger.LogDebug("Got person: {Name}", p.Name))
    .Where(p => p.IsActive)
    .Do(p => logger.LogDebug("Active person: {Name}", p.Name))
    .Select(p => p.Address)
    .Do(a => logger.LogDebug("Address: {City}", a.City))
    .Select(a => a.City)
    .ToList();

// Unlike ToList() + ForEach(), this maintains the pipeline
var query = GetData()
    .Do(x => Console.WriteLine($"Item: {x}"))  // Lazy, not executed yet
    .Where(x => x.IsValid);

// Action only executes when enumerated
foreach (var item in query) { }  // NOW the Do action runs

var people = GetPeople()
    .Where(p => p.IsActive)
    .ForEach(p => p.Status = "Processed"); // Returns List, executes immediately

// Chaining is still possible
var count = GetPeople()
    .ForEach(p => logger.Log(p.Name))
    .Count;

var people = await GetPeople()
    .Where(p => p.IsActive)
    .ForEachAsync(async (p, ct) => await ProcessAsync(p, ct), ct); // Returns Task of List

// Chaining is still possible
var count = (await GetPeople()
    .ForEachAsync(async (p, ct) => await EnrichAsync(p, ct), ct))
    .Count;

// Get data async, then process with sync logging
var result = await GetPeopleAsync()
    .ThenDo(p => logger.Log(p.Name))
    .Select(p => p.Process())
    .ToListAsync();

// Encode and decode with UTF-8 (default)
var original = "Hello, World!";
var base64 = original.Fx.Encoding.ToBase64String();  // "SGVsbG8sIFdvcmxkIQ=="
var decoded = base64.Payload.Fx.Encoding.DecodeFromBase64();
Console.WriteLine(decoded.Payload);  // Output: "Hello, World!"

// Using a different encoding
var base64Latin1 = "SGVsbG8sIFdvcmxkIQ==";
var decodedLatin1 = base64Latin1.Fx.Encoding.DecodeFromBase64(Encoding.Latin1);

// Encode with UTF-8 (default)
var text = "Hello, World!";
var response = text.Fx.Encoding.ToBase64String();
Console.WriteLine(response.Payload);  // Output: "SGVsbG8sIFdvcmxkIQ=="

// Encode with a different encoding
var textLatin1 = "Café";
var responseLatin1 = textLatin1.Fx.Encoding.ToBase64String(Encoding.Latin1);

// Round-trip example
var original = "Test data 123";
var encoded = original.Fx.Encoding.ToBase64String();
var decoded = encoded.Payload.Fx.Encoding.DecodeFromBase64();
Console.WriteLine(decoded.Payload);  // Output: "Test data 123"

// Encode and decode with UTF-8 (default)
var original = "Hello, World!";
var base64Url = original.Fx.Encoding.ToBase64UrlString();  // "SGVsbG8sIFdvcmxkIQ" (no padding)
var decoded = base64Url.Payload.Fx.Encoding.DecodeFromBase64Url();
Console.WriteLine(decoded.Payload);  // Output: "Hello, World!"

// URL-safe characters example
var urlData = "test+data/value";
var encoded = urlData.Fx.Encoding.ToBase64UrlString();  // Uses '-' and '_' instead of '+' and '/'
var decodedUrl = encoded.Payload.Fx.Encoding.DecodeFromBase64Url();
Console.WriteLine(decodedUrl.Payload);  // Output: "test+data/value"

// Using a different encoding
var base64UrlLatin1 = "SGVsbG8";
var decodedLatin1 = base64UrlLatin1.Fx.Encoding.DecodeFromBase64Url(Encoding.Latin1);

// Encode with UTF-8 (default)
var text = "Hello, World!";
var response = text.Fx.Encoding.ToBase64UrlString();
Console.WriteLine(response.Payload);  // Output: "SGVsbG8sIFdvcmxkIQ" (no padding)

// Compare with regular Base64
var base64 = text.Fx.Encoding.ToBase64String().Payload;        // "SGVsbG8sIFdvcmxkIQ=="
var base64Url = text.Fx.Encoding.ToBase64UrlString().Payload;  // "SGVsbG8sIFdvcmxkIQ"

// URL-safe usage
var urlData = "user+id/session";
var urlSafe = urlData.Fx.Encoding.ToBase64UrlString();
// Can be safely used in URLs: https://example.com/api?token={urlSafe.Payload}

// Round-trip example
var original = "Test data 123";
var encoded = original.Fx.Encoding.ToBase64UrlString();
var decoded = encoded.Payload.Fx.Encoding.DecodeFromBase64Url();
Console.WriteLine(decoded.Payload);  // Output: "Test data 123"

var connection = CreateConnection();
using var envelope = connection.Fx.Lifetime.AsDisposable(conn => conn.Close());

// Access wrapped value explicitly via .Value property
envelope.Value.SendData("test");

// Or use implicit conversion (envelope is automatically converted to Connection)
envelope.SendData("test");  // Calls SendData directly on the wrapped connection

// Connection will be closed automatically when the using block exits

// Example with null value
Connection? nullConnection = null;
using var nullEnvelope = nullConnection.Fx.Lifetime.AsDisposable(conn => conn.Close());
// Returns DisposableEnvelope<Connection>.Disposed (already disposed, no action executed)

var stream = OpenStreamAsync();
await using var envelope = stream.Fx.Lifetime.AsDisposableAsync(async s => await s.FlushAsync());

// Access wrapped value explicitly via .Value property
await envelope.Value.WriteAsync(data);

// Or use implicit conversion (envelope is automatically converted to Stream)
await envelope.WriteAsync(data);  // Calls WriteAsync directly on the wrapped stream

// Stream will be flushed asynchronously when the await using block exits

// Example with database connection
var dbConnection = await GetDatabaseConnectionAsync();
await using var dbEnvelope = dbConnection.Fx.Lifetime.AsDisposableAsync(async conn => 
{
    await conn.CommitTransactionAsync();
    await conn.CloseAsync();
});

// Use implicit conversion for cleaner code
var result = await dbEnvelope.ExecuteQueryAsync("SELECT * FROM Users");

// Database transaction committed and connection closed asynchronously on disposal

// Example with null value
Stream? nullStream = null;
await using var nullEnvelope = nullStream.Fx.Lifetime.AsDisposableAsync(async s => await s.FlushAsync());
// Returns DisposableEnvelope<Stream>.Disposed (already disposed, no function executed)

member.returns:
A  whose payload is a tuple with  Quotient and Remainder
when the underlying value is not null and  is not zero;
otherwise, an error response indicating that the source value is null or the divisor is invalid.

A  whose payload is a tuple with  Quotient and Remainder
when the underlying value is not null and  is in range;
otherwise, an error response describing the problem.

A  whose payload is a tuple with  Quotient and Remainder
when the underlying value is not null and  is not zero;
otherwise, an error response indicating that the source value is null or the divisor is invalid.

A  whose payload is a tuple with  Quotient and Remainder
when the underlying value is not null and  is in range;
otherwise, an error response describing the problem.

true when the underlying path starts with  and both paths are valid;
false when the underlying path doesn't start with ,
or when either the underlying value or  is null, empty, or only whitespace.

example.code:
// On Windows (case-insensitive by default):
"c:\\foobar\\file.txt".Fx.Path.IsSubPathOf("c:\\foo")      // returns false (exact folder name match required)
"c:\\foo\\bar\\file.txt".Fx.Path.IsSubPathOf("c:\\foo")    // returns true
"c:\\FOO\\bar\\file.txt".Fx.Path.IsSubPathOf("c:\\foo")    // returns true (case-insensitive on Windows)
"c:/foo/bar/file.txt".Fx.Path.IsSubPathOf("c:\\foo")       // returns true (handles mixed separators)

// On Unix (case-sensitive by default):
"/home/user/file.txt".Fx.Path.IsSubPathOf("/home/user")    // returns true
"/home/USER/file.txt".Fx.Path.IsSubPathOf("/home/user")    // returns false (case-sensitive on Unix)

// Explicit comparison type:
"c:\\FOO\\file.txt".Fx.Path.IsSubPathOf("c:\\foo", StringComparison.Ordinal)  // returns false (case-sensitive)

var path1 = "c:\\folder".Fx.Path;
var path2 = "subfolder\\file.txt".Fx.Path;
var combined = path1 / path2;  // returns "c:\folder\subfolder\file.txt" (on Windows)

var unixPath1 = "/home/user".Fx.Path;
var unixPath2 = "documents/file.txt".Fx.Path;
var unixCombined = unixPath1 / unixPath2;  // returns "/home/user/documents/file.txt" (on Unix)

// Generate password with custom charset
var charset = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%";
var password = charset.RandomString(12);  // e.g., "A3#9X@M2K5P!"

// Generate hexadecimal string
var hex = "0123456789ABCDEF".RandomString(8);  // e.g., "3FA8C12D"

// Empty/null uses default charset
var random = "".RandomString(10);  // Uses "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"

member.remarks:
Index is used by the C# compiler to support the new index syntax

int[] someArray = new int[5] { 1, 2, 3, 4, 5 } ;
int lastElement = someArray[^1]; // lastElement = 5

Range is used by the C# compiler to support the range syntax.

int[] someArray = new int[5] { 1, 2, 3, 4, 5 };
int[] subArray1 = someArray[0..2]; // { 1, 2 }
int[] subArray2 = someArray[1..^0]; // { 2, 3, 4, 5 }

example.code:
var method = typeof(MyClass).GetMethod("MyMethod");
var attr = method.GetCustomAttribute<ObsoleteAttribute>();
if (attr != null)
{
    Console.WriteLine($"Method is obsolete: {attr.Message}");
}

// Throw exception if not found
var requiredAttr = method.GetCustomAttribute<RequiredAttribute>(exceptionIfNotFound: true);

var method = typeof(MyClass).GetMethod("MyMethod");
if (method.HasCustomAttribute<ObsoleteAttribute>())
{
    Console.WriteLine("Method is marked as obsolete");
}

var method = typeof(MyClass).GetMethod("ProcessDataAsync");

// Simple signature
var simple = method.GetSignature();
// Output: "MyClass.ProcessDataAsync(string, int)"

// Full signature with modifiers and return type
var full = method.GetSignature(
    includeAccessModifiers: true,
    includeReturn: true,
    includeParametersNames: true);
// Output: "public async Task MyClass.ProcessDataAsync(string data, int timeout)"

// Minimal signature without declaring type
var minimal = method.GetSignature(includeDeclaringType: false);
// Output: "ProcessDataAsync(string, int)"

